/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        window.SlotsFacade = this; // 创建个全局变量，以便子模块方便访问
        this.dm = cc.vv.gameData;
        this.InitCommComponent();

        // wheel
        let wheel_script = cc.find("safe_node/wheel", this.node).getComponent("TheMammoth_Wheel");
        cc.vv.gameData.GetSlotsScript().setWheelScripts(wheel_script);
        this.wheel = wheel_script;

        // 设置基类快捷索引
        this.topCmp = cc.vv.gameData.GetTopScript();
        this.bottomCmp = cc.vv.gameData.GetBottomScript();
        this.slots = cc.vv.gameData.GetSlotsScript();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onUpdateBet, this);
    },

    onDestroy() {
        window.SlotsFacade = null;
        this.dm = null;
    },

    delayTime(time) {
        return new Promise((res, rej) => {
            this.scheduleOnce(()=>{res()}, time);
        });
    },

    onUpdateBet: function () {
        cc.vv.gameData.GetSlotsScript().updateFreePanel(cc.vv.gameData.GetBetIdx() - 1);
    },

    playPrizePoolAnimation() {
        let grand = cc.find("safe_node/LMSlots_PrizePool_1/prizePool_Grand", this.node);
        grand.opacity = 255;
        let major = cc.find("safe_node/LMSlots_PrizePool_1/prizePool_Major", this.node);
        major.opacity = 0;
        let minor = cc.find("safe_node/LMSlots_PrizePool_1/prizePool_Minor", this.node);
        minor.opacity = 0;

        grand.runAction(cc.repeatForever(
            cc.sequence(
                cc.delayTime(4),
                cc.fadeOut(0.5),
                cc.delayTime(8.5),
                cc.fadeIn(0.5)
            )
        ));

        major.runAction(cc.repeatForever(
            cc.sequence(
                cc.delayTime(4),
                cc.fadeIn(0.5),
                cc.delayTime(4),
                cc.fadeOut(0.5),
                cc.delayTime(4.5),
            )
        ));

        minor.runAction(cc.repeatForever(
            cc.sequence(
                cc.delayTime(8.5),
                cc.fadeIn(0.5),
                cc.delayTime(4),
                cc.fadeOut(0.5)
            )
        ));
    },

    start() {
        this._super();
        this.playPrizePoolAnimation();
    }
});