/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    StartMove: function () {
        this._super();
    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById: function (id, data) {
        this._super(id, data);
    },

    //赢钱动画
    playWinAnimation() {
        if (this._showNode) {
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            this._state = "win";
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true;
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true
            if (cfg.symbol[id].win_ani && cfg.symbol[id].win_ani.name !== "") {
                aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    // if (id !== 3) {
                        nodeSp.setAnimation(0, cfg.symbol[id].win_ani.name, true)
                    // } else {
                    //     nodeSp.setAnimation(0, cfg.symbol[id].win_ani.name, false);
                    //     nodeSp.setCompleteListener((track) => {
                    //         let name = track.animation ? track.animation.name : "";
                    //         if (name === cfg.symbol[id].win_ani.name) {
                    //             nodeSp.clearTracks();
                    //             nodeSp.setAnimation(0, "animation2", true);
                    //         }
                    //     });
                    // }
                }
            }
        } else {
            //如果没有中奖动画，先显示出来
            //TODO：后续补充一个没有spin动画的显示效果
            this._showNode.active = true
            this.playWinTweenAction()
        }
    },

    playWildAnimation(rate) {
        if (this._showNode) {
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()

        this._state = "win";
        if (this._showNode) {
            this._showNode.active = false
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true;
        if (cc.vv.gameData.GetTotalFree() > 0 &&
            cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime() &&
            id === cfg.wildId) {
            let topShowNode = cc.find("animation_1_" + rate, aniNode)
            topShowNode.active = true

            aniNode.zIndex = 300 - this._symbolIdx + this._reelIdx * 10;
            let nodeSp = topShowNode.getComponent(sp.Skeleton)
            if (nodeSp) {

                nodeSp.setAnimation(0, "animation1", false);
                nodeSp.setCompleteListener((track) => {
                    let name = track.animation ? track.animation.name : "";
                    if (name === "animation1") {
                        nodeSp.clearTracks();
                        nodeSp.setAnimation(0, "animation", true);
                    }
                });
            }
        }
    },

    playWinTweenAction() {
        this._showNode.cleanup()
        //记录原始缩放
        this._showNodeOrgScale = this._showNode.scale

        cc.tween(this._showNode)
            .repeatForever(cc.tween()
                .to(0.35, {opacity: 0})
                .to(0.35, {opacity: 255})
                .delay(1)
            )
            .start()
    },

    // update (dt) {},
});
