/**
 * @description
 */

let WheelItemType = {
    FreeGame: 1,
    Jackpot: 2,
    FreeGameMult: 3
};

cc.Class({
    extends: cc.Component,
    properties:{
        type_1: cc.Node,
        type_2: cc.Node,
        btn_play: cc.Node,
        sanjiao: cc.Node,
        shuihua: cc.Node,
        jinse: cc.Node,
        zise: cc.Node,
        jackpot_result: cc.Node,
        jackpot_result_bg: cc.Node,
        minor: cc.Node,
        major: cc.Node,
        grand: cc.Node,

        items_1: [cc.Node],
        items_2: [cc.Node],


        speed: {
            default: 1,
            tooltip: "旋转速度"
        },
        maxSpeed: {
            default: 20,
            tooltip: "最大速度",
        },
        count: {
            default: 2,
            tooltip: "需要转几轮",
        },
        minSpeed: {
            default: 1,
            tooltip: "最小速度"
        },
        speedOffset: {
            default: 0.25,
            tooltip: "速度变化值",
        },

        _startMove: false,
        _needStop: false,
        _backMove: false,

        _resultItem: null,        // 结果索引 从1开始
        _bottomPosY: 0,

        _successCallback: null,

        _hasPressed: false,

        _result: null,
        _wheelConfig: null,
        _type: 1,
        _items: null,

        _itemsHeight: 0,
    },

    onLoad() {
        this.btn_play.on("click", ()=>{
            if (this._hasPressed) {
                return;
            }
            this.btn_play.stopAllActions();
            cc.vv.AudioManager.playEff("games/TheMammoth/", "fg_select", true);
            
            this._hasPressed = true;

            let req = {c: MsgId.SLOT_SUBGAME_DATA};
            req.gameid = cc.vv.gameData.getGameId();
            req.data = {};
            req.data.rtype = 1;

            cc.vv.NetManager.send(req, true);

            this.btn_play.runAction(cc.fadeOut(0.2));
        });

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubgameData, this);
    },

    update(dt) {
        if (this._startMove) {
            if (!this._needStop) {
                this.speed += this.speedOffset;
                if (this.speed >= this.maxSpeed) {
                    this.speed = this.maxSpeed;
                }
            } else {
                this.speed -= this.speedOffset;
                if (this.speed <= this.minSpeed) {
                    this.speed = this.minSpeed;
                }
            }

            if (this.count === 0 && this._resultItem.y <= 3 * this._resultItem.height) {
                this._needStop = true;
            }

            if (this._needStop && this._resultItem.y < -180) {
                this._startMove = false;
                this._backMove = true;
            }

            for (let item of this._items) {
                if (item.y <= this._bottomPosY) {
                    item.y += this._itemsHeight;
                    if (item === this._resultItem) {
                        this.count--;
                        if (this.count <= 0) {
                            this.count = 0;
                        }
                    }
                }

                item.y -= this.speed;
            }
        }

        if (this._backMove) {
            for (let item of this._items) {
                item.y += this.minSpeed;
            }

            if (this._resultItem.y > -181 && this._resultItem.y < -179) {
                this._backMove = false;
                this.exitWheelGame();
            }
        }
    },

    onRcvSubgameData(msg) {
        if (msg.code === 200 && msg.data.rtype === 1) {
            this._resultItem = this._items[msg.data.itemId - 1];

            this._result = msg.data;

            cc.vv.gameData.GetSlotsScript().setWheelResult(this._result);

            this._startMove = true;

            cc.vv.AudioManager.playEff("games/TheMammoth/", "bonus_wheel_spin", true);

            let cfg = this._wheelConfig[msg.data.itemId - 1];
            if (cfg.type === WheelItemType.FreeGame || cfg.type === WheelItemType.FreeGameMult) {
                cc.vv.gameData.SetTotalFree(cfg.freeCnt);
                cc.vv.gameData.SetFreeTime(cfg.freeCnt);
            }

            this.shuihua.active = true;
            this.shuihua.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
            this.shuihua.getComponent(sp.Skeleton).setCompleteListener((track)=>{
                let name = track.animation ? track.animation.name : "";
                if (name === "animation1") {
                    this.shuihua.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
                }
            });
        }
    },

    async enterWheelGame(successCallback, wheelConfig) {
        this.node.active = true;
        this.reset();
        this._successCallback = successCallback;
        this._wheelConfig = wheelConfig;

        cc.vv.AudioManager.playBgm("games/TheMammoth/", "bonus_bgm", true);

        let deskInfo = cc.vv.gameData.getDeskInfo();
        let parentType = null;
        if (deskInfo.needBet > cc.vv.gameData.GetBetIdx()) {
            // 带普通免费
            this._type = 1;
            parentType = cc.find("bg/wheel_mask/type_1", this.node);
            parentType.active = true;
            cc.find("bg/wheel_mask/type_2", this.node).active = false;
        } else {
            // 不带普通免费
            this._type = 2;
            parentType = cc.find("bg/wheel_mask/type_2", this.node);
            parentType.active = true;
            cc.find("bg/wheel_mask/type_1", this.node).active = false;
        }

        this._items = this._type === 1 ? this.items_1 : this.items_2;

        this._itemsHeight = 0;
        for (let item of this._items) {
            this._itemsHeight += item.height;
        }

        // 最下边的位置
        this._bottomPosY = -708;



            for (let i = 0; i < wheelConfig.length; i++) {
                let cfg = wheelConfig[i];
                let node = cc.find("index_" + (i + 1), parentType);
                if (cfg.type === WheelItemType.FreeGame) {
                    cc.find("num", node).getComponent(cc.Label).string = cfg.freeCnt;
                } else if (cfg.type === WheelItemType.Jackpot) {
                    cc.find("num", node).getComponent(cc.Label).string = Global.convertNumToShort(cfg.jackpotValue, null, 0);
                } else {
                    cc.find("num", node).getComponent(cc.Label).string = cfg.freeCnt;
                }
            }


        cc.vv.gameData.checkAutoPlay(this.btn_play, ()=>{
            if (this._hasPressed) {
                return;
            }
            cc.vv.AudioManager.playEff("games/TheMammoth/", "fg_select", true);

            this._hasPressed = true;

            let req = {c: MsgId.SLOT_SUBGAME_DATA};
            req.gameid = cc.vv.gameData.getGameId();
            req.data = {};
            req.data.rtype = 1;

            cc.vv.NetManager.send(req, true);

            this.btn_play.runAction(cc.fadeOut(0.2));
        });
    },

    async exitWheelGame() {
        // 箭头特效
        cc.vv.AudioManager.playEff("games/TheMammoth/", "bonus_active", true);

        this.sanjiao.active = true;
        this.sanjiao.getComponent(sp.Skeleton).setToSetupPose();
        this.sanjiao.getComponent(sp.Skeleton).setAnimation(0, "animation", false);

        this.shuihua.getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
        this.shuihua.getComponent(sp.Skeleton).setCompleteListener((track)=>{
            let name = track.animation ? track.animation.name : "";
            if (name === "animation3") {
                this.shuihua.active = false;
            }
        });

        await this.awaitTime(1);

        let cfg = this._wheelConfig[this._result.itemId - 1];
        if (cfg.type === WheelItemType.FreeGame) {
            this.zise.active = true;
            this.zise.getComponent(sp.Skeleton).setToSetupPose();
            this.zise.getComponent(sp.Skeleton).setAnimation(0, "animation", true);
        } else if (cfg.type === WheelItemType.Jackpot) {
            this.jinse.active = true;
            this.jinse.getComponent(sp.Skeleton).setToSetupPose();
            this.jinse.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
        } else {
            this.jinse.active = true;
            this.jinse.getComponent(sp.Skeleton).setToSetupPose();
            this.jinse.getComponent(sp.Skeleton).setAnimation(0, "animation1", true);
        }

        await this.awaitTime(2);

        if (cfg.type === WheelItemType.Jackpot) {
            cc.vv.AudioManager.playEff("games/TheMammoth/", "jp_board", true);

            this.jackpot_result.active = true;
            this.jackpot_result_bg.opacity = 0;
            this.jackpot_result_bg.runAction(cc.fadeTo(0.2, 200));

            this.minor.active = false;
            this.major.active = false;
            this.grand.active = false;

            let result_node = null;
            if (this._result.jackpot.id === 2) {
                result_node = this.minor;
            } else if (this._result.jackpot.id === 3) {
                result_node = this.major;
            } else {
                result_node = this.grand;
            }

            result_node.active = true;
            result_node.scale = 0;
            result_node.runAction(cc.scaleTo(0.4, 1).easing(cc.easeBackOut()));

            Global.doRoallNumEff(result_node.getChildByName("num"), 0, this._result.jackpot.value, 3, null, null, 0, true);

            result_node.getChildByName("btn_collect").on("click", ()=>{
                this.jackpot_result_bg.runAction(cc.fadeOut(0.2));

                result_node.runAction(cc.sequence(
                    cc.scaleTo(0.4, 0).easing(cc.easeBackIn()),
                    cc.callFunc(()=>{
                        if (this._successCallback) {
                            this._successCallback();
                        }
                    })
                ))
            });
        } else {
            if (this._successCallback) {
                this._successCallback();
            }
        }
    },

    reset() {
        this._startMove = false;
        this.speed = 1;
        this._needStop = false;
        this.count = 2;
        this._hasPressed = false;
        this._backMove = false;

        this.zise.active = false;
        this.jinse.active = false;
        this.btn_play.opacity = 255;
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubgameData, false, this);
    },

    awaitTime(dt) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, dt);
        });
    }
});