/**
 * @description
 */

let WheelItemType = {
    FreeGame: 1,
    Jackpot: 2,
    FreeGameMult: 3
};

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _wheel_script: null,
        _wheel_result: null,
        _curFreeTimesPanel: null,
    },

    Init() {
        this._super();

        this.updateFreePanel(cc.vv.gameData.GetBetIdx() - 1);

        if (cc.winSize.height / cc.winSize.width > 2.1) {
            cc.find("logo", this.node.parent).active = true;
        } else {
            cc.find("logo", this.node.parent).active = false;
        }

        this.node.parent.parent.getComponent("LMSlots_Puzzle").setCallback(async (freeInfo, chipGame)=>{
            // 进入免费的逻辑
            cc.vv.gameData.SetTotalFree(freeInfo.freeCnt);
            cc.vv.gameData.SetFreeTime(freeInfo.freeCnt);

            this.cutScenesElephant();

            await cc.vv.gameData.awaitTime(1.5);

            this.ShowGameview(true);

            this.changeFreeBg(true);

            await cc.vv.gameData.awaitTime(1.5);

            await this.popFreeDialog(true);

            cc.vv.AudioManager.playBgm("games/TheMammoth/", "free_bgm", true);

            this.CanDoNextRound();
        });
    },

    //点击旋转按钮调用
    StartMove:function(){
        this._super();

        Global.SlotsSoundMgr.playNormalBgm();

        if (this._curFreeTimesPanel) {
            cc.find("allTimes", this._curFreeTimesPanel).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
            cc.find("curTimes", this._curFreeTimesPanel).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree() - cc.vv.gameData.GetFreeTime();
        }
    },

    async ReconnectShow() {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        let wheelGame = deskInfo.history.wheelGames[cc.vv.gameData.GetBetIdx() - 1];
        if (wheelGame.state === 1) {
            // 进入转盘
            await new Promise((success)=>{
                this._wheel_script.enterWheelGame(success, wheelGame.items);
            });

            let cfg = wheelGame.items[this._wheel_result.itemId - 1];
            if (cfg.type === WheelItemType.Jackpot) {
                this.cutScenesIce();

                await cc.vv.gameData.awaitTime(1.5);
                this._wheel_script.reset();
                this._wheel_script.node.active = false;

                cc.vv.gameData.AddCoin(this._wheel_result.jackpot.value);

                this.ShowBottomWin(this._wheel_result.jackpot.value, this._wheel_result.jackpot.value, true, ()=>{
                    this.CanDoNextRound();
                });
            } else if (cfg.type === WheelItemType.FreeGame) {
                this.cutScenesElephant();

                this.ShowGameview(true);

                this.changeFreeBg(true);

                await cc.vv.gameData.awaitTime(1.5);
                this._wheel_script.reset();
                this._wheel_script.node.active = false;

                await this.popFreeDialog(true);

                this.CanDoNextRound();
            } else if (cfg.type === WheelItemType.FreeGameMult) {
                this.cutScenesElephant();

                this.ShowGameview(true);

                this.changeFreeBg(false, cfg.mult);

                await cc.vv.gameData.awaitTime(1.5);
                this._wheel_script.reset();
                this._wheel_script.node.active = false;

                await this.popFreeDialog(false, false, cfg.mult);

                this.CanDoNextRound();
            }
        } else {
            if (cc.vv.gameData.GetFreeTime() > 0) {
                if (deskInfo.addMult === 1) {
                    this.changeFreeBg(true);
                } else {
                    this.changeFreeBg(false, deskInfo.addMult);
                }
                this.ShowGameview(true);

                this.CanDoNextRound();
            } else {
                this.ShowGameview(false);
            }
        }
    },

    async onMsgSpine(msg) {
        this._super(msg);

        // 随机游戏
        if (this._gameInfo.mammothGame) {
            this.SetStopTime(3);

            this.triggerRandomGame();
        }

        cc.vv.gameData.getDeskInfo().history.wheelGames[cc.vv.gameData.GetBetIdx() - 1] = this._gameInfo.wheelGame;
    },

    //检查进入免费
    CheckEnterFreeGame:function(){
        return this._gameInfo.wheelGame.state === 1;
    },

    CheckExtraFreeGame() {
        return !!(this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0);
    },

    CheckExitFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === 0;
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    async ShowWinTrace(){
        return new Promise(async (success)=>{
            let allWinIdx = []

            //中奖位置
            for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
                let item = this._gameInfo.zjLuXian[i]
                for(let idx = 0; idx < item.indexs.length; idx++){
                    allWinIdx[item.indexs[idx]] = 1
                }
            }
            if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
                for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                    let val = this._gameInfo.scatterZJLuXian.indexs[i]
                    allWinIdx[val] = 1
                }
            }

            if (cc.vv.gameData.GetTotalFree() > 0 &&
                cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
                let hasWild = false;
                for (const key in allWinIdx) {
                    let symbol = this.GetSymbolByIdx(Number(key))
                    if(symbol){
                        if (symbol.GetShowId() === this._cfg.wildId) {
                            hasWild = true;
                            symbol.playWildAnimation(this._gameInfo.wildMult);
                        }
                    }
                }
                if (hasWild) {
                    cc.vv.AudioManager.playEff("games/TheMammoth/", "wild_land_2", true);
                    await cc.vv.gameData.awaitTime(1.5);
                }
            }

            //总
            for (const key in allWinIdx) {
                let symbol = this.GetSymbolByIdx(Number(key))
                if(symbol){
                    if (cc.vv.gameData.GetTotalFree() > 0 &&
                        cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime() &&
                        symbol.GetShowId() === this._cfg.wildId) {

                    } else {
                        symbol.playWinAnimation()
                    }
                    symbol.ShowKuang()
                }
            }

            success();
        });
    },

    //重写：显示bonus中奖
    async OnSpinEnd() {
        await this.ShowWinTrace();

        this.playAddFreeTimesAnimation();

        let winCoin = cc.vv.gameData.GetGameWin();
        let totalWinCoin = cc.vv.gameData.GetGameWin();
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            // 免费中
            totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin();
        }

        this.ShowBottomWin(winCoin, totalWinCoin, true, async ()=>{
            if (this.CheckEnterFreeGame()) {
                this.triggerFreeGame();
            } else if (this.CheckExtraFreeGame()) {
                this.triggerExtraFreeGame();
            } else {
                if (this.CheckExitFreeGame()) {
                    this.triggerExitFreeGame();
                } else {
                    await cc.vv.gameData.awaitTime(0.1);

                    this.CanDoNextRound();
                }
            }
        });
    },

    playAddFreeTimesAnimation() {
        if (this._gameInfo.updateWheel) {
            let animationIndex = 1;
            if (this._gameInfo.updateWheel.mult === 3) {
                animationIndex = 2;
            } else if (this._gameInfo.updateWheel.mult === 5) {
                animationIndex = 3;
            }

            let endPos = cc.find("free_panel/free_" + animationIndex + "/times", this.node.parent).convertToWorldSpaceAR(cc.v2(0, 0));
            endPos = this.node.parent.convertToNodeSpaceAR(endPos);

            cc.vv.AudioManager.playEff("games/TheMammoth/", "gem", true);

            let spine = cc.instantiate(cc.find("zhuanshi_01", this.node.parent));
            spine.active = true;

            let position = null;
            let reel = this._reels[4];
            for (let i = 0; i < this._cfg.row; i++) {
                let symbol = reel.GetSymbolByRow(i);
                if (symbol.GetShowId() === 14) {
                    position = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    position = this.node.parent.convertToNodeSpaceAR(position);
                    break;
                }
            }

            spine.position = position;
            spine.parent = this.node.parent;
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation" + animationIndex, false);
            spine.getComponent(sp.Skeleton).setCompleteListener((track)=>{
                let name = track.animation ? track.animation.name : "";
                if (name === "animation" + animationIndex) {
                    spine.getComponent(sp.Skeleton).clearTracks();
                    spine.getComponent(sp.Skeleton).setAnimation(0, "animation" + animationIndex + "_1", false);
                    spine.runAction(cc.sequence(
                        cc.moveTo(0.5, endPos),
                        cc.callFunc(()=>{
                            let shuzizengjia = cc.instantiate(cc.find("shuzizengjia_01", this.node.parent));
                            shuzizengjia.active = true;
                            shuzizengjia.parent = this.node.parent;
                            shuzizengjia.position = endPos;
                            shuzizengjia.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                            shuzizengjia.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                shuzizengjia.removeFromParent();
                            });

                            this.updateFreePanel(cc.vv.gameData.GetBetIdx() - 1);

                            spine.removeFromParent();
                        })
                    ));
                }
            });
        }
    },

    async triggerFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === 2 || card === 14) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        cc.vv.AudioManager.playEff("games/TheMammoth/", "bell", true);
        // 触发免费游戏
        await cc.vv.gameData.awaitTime(2);

        this.cutScenesIce();

        await cc.vv.gameData.awaitTime(0.5);

        await new Promise((success)=>{
            this._wheel_script.enterWheelGame(success, this._gameInfo.wheelGame.items);
        });

        let cfg = this._gameInfo.wheelGame.items[this._wheel_result.itemId - 1];
        if (cfg.type === WheelItemType.Jackpot) {
            this.cutScenesIce();

            await cc.vv.gameData.awaitTime(1.5);
            cc.vv.gameData.AddCoin(this._wheel_result.jackpot.value);
            this._wheel_script.reset();
            this._wheel_script.node.active = false;

            this.ShowBottomWin(this._wheel_result.jackpot.value, this._wheel_result.jackpot.value, true, ()=>{
                this.CanDoNextRound();
            });
        } else if (cfg.type === WheelItemType.FreeGame) {
            this.cutScenesElephant();
            this.Backup();

            this.ShowGameview(true);

            this.changeFreeBg(true);

            await cc.vv.gameData.awaitTime(1.5);
            this._wheel_script.reset();
            this._wheel_script.node.active = false;

            await this.popFreeDialog(true);

            cc.vv.AudioManager.playBgm("games/TheMammoth/", "free_bgm", true);

            this.CanDoNextRound();
        } else if (cfg.type === WheelItemType.FreeGameMult) {
            this.cutScenesElephant();
            this.Backup();

            this.ShowGameview(true);

            this.changeFreeBg(false, cfg.mult);

            await cc.vv.gameData.awaitTime(1.5);
            this._wheel_script.reset();
            this._wheel_script.node.active = false;

            await this.popFreeDialog(false, false, cfg.mult);

            cc.vv.AudioManager.playBgm("games/TheMammoth/", "free_bgm", true);

            this.CanDoNextRound();
        }
    },

    async triggerExtraFreeGame() {
        this._bottomScript.ShowBtnsByState("stopped");

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === 2 || card === 14) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        cc.vv.AudioManager.playEff("games/TheMammoth/", "bell", true);

        await cc.vv.gameData.awaitTime(2);

        await this.popFreeDialog(false, true);

        this.CanDoNextRound();
    },

    async triggerExitFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        await cc.vv.gameData.awaitTime(1);

        await this.popFreeResultDialog();

        this.cutScenesElephant();

        this._curFreeTimesPanel = null;

        await cc.vv.gameData.awaitTime(1.5);

        this.updateFreePanel(cc.vv.gameData.GetBetIdx() - 1);

        this.ShowGameview(false);
        this.Resume();

        this.ShowBottomWin(cc.vv.gameData.GetGameTotalFreeWin(), cc.vv.gameData.GetGameTotalFreeWin(), true, ()=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            this.CanDoNextRound();
        });
    },

    setWheelScripts(script) {
        this._wheel_script = script;
    },

    setWheelResult(result) {
        this._wheel_result = result;
    },

    cutScenesIce() {
        cc.vv.AudioManager.playEff("games/TheMammoth/", "bonus_transiton", true);
        let qp_02 = cc.find("qp_02", this.node.parent);
        qp_02.active = true;
        qp_02.getComponent(sp.Skeleton).setToSetupPose();
        qp_02.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
    },

    cutScenesElephant() {
        cc.vv.AudioManager.playEff("games/TheMammoth/", "fg_transiton", true);
        let QP_01 = cc.find("QP_01", this.node.parent);
        QP_01.active = true;
        QP_01.getComponent(sp.Skeleton).setToSetupPose();
        QP_01.getComponent(sp.Skeleton).setAnimation(0, "idle3", false);
    },

    //单列停止
    OnReelSpinEnd(colIdx) {
        this._super(colIdx);
    },

    SetSlotsResult: function (cards) {
        this._super(cards);
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        this._super(bFree);

        cc.find("free_panel", this.node.parent).active = !bFree;

        cc.find("LMSlots_PrizePool_1", this.node.parent).active = !bFree;
        let free_times = cc.find("free_times", this.node.parent);
        free_times.active = bFree;

        cc.find("LMSlots_Collect_Puzzle", this.node.parent).active = !bFree;
    },

    update(dt) {
        this._super(dt);
    },

    shake() {
        let safe_node = this.node.parent;
        for (let child of safe_node.children) {
            if (child.name !== "LMSlots_Top" && child.name !== "LMSlots_Bottom" && child.active) {
                let action = cc.shake(3, 15, 15);
                child.runAction(action);
            }
        }
    },
    
    triggerRandomGame() {
        cc.vv.AudioManager.playEff("games/TheMammoth/", "big_win_transiton", true);
        let spine = cc.find("spine_randomgame", this.node);
        spine.active = true;
        spine.getComponent(sp.Skeleton).setToSetupPose();
        spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);

        this.shake();
    },

    updateFreePanel(curMult) {
        let history = cc.vv.gameData.getDeskInfo().history;
        if (history && history.wheelGames && curMult < history.wheelGames.length) {
            let wheel = history.wheelGames[curMult];
            let greenTimes = cc.find("free_panel/free_1/times", this.node.parent);
            let purpleTimes = cc.find("free_panel/free_2/times", this.node.parent);
            let redTimes = cc.find("free_panel/free_3/times", this.node.parent);
            greenTimes.getComponent(cc.Label).string = wheel.greenItem.freeCnt;
            purpleTimes.getComponent(cc.Label).string = wheel.purpleItem.freeCnt;
            redTimes.getComponent(cc.Label).string = wheel.redItem.freeCnt;
        }

        let tip_1 = cc.find("free_panel/tip/tip_1", this.node.parent);   // 不足
        let tip_2 = cc.find("free_panel/tip/tip_2", this.node.parent);   // 足
        let qiehuan = cc.find("free_panel/tip/qiehuan_01", this.node.parent);
        let spine = qiehuan.getComponent(sp.Skeleton);
        if (curMult >= cc.vv.gameData.getDeskInfo().needBet) {
            if (!tip_2.active) {
                qiehuan.active = true;
                spine.setToSetupPose();
                spine.setAnimation(0, "animation", false);
                spine.setCompleteListener(()=>{
                    qiehuan.active = false;
                });
            }




            tip_1.active = false;
            tip_2.active = true;
        } else {
            if (!tip_1.active) {
                qiehuan.active = true;
                spine.setToSetupPose();
                spine.setAnimation(0, "animation", false);
                spine.setCompleteListener(()=>{
                    qiehuan.active = false;
                });
            }

            tip_1.active = true;
            tip_2.active = false;
        }
    },

    changeFreeBg(isCommon, mult) {
        cc.find("LMSlots_PrizePool_1", this.node.parent).active = false;
        let free_times = cc.find("free_times", this.node.parent);
        free_times.active = true;
        cc.find("common", free_times).active = false;
        cc.find("mult_2", free_times).active = false;
        cc.find("mult_3", free_times).active = false;
        cc.find("mult_5", free_times).active = false;
        if (isCommon) {
            this._curFreeTimesPanel = cc.find("common", free_times);
            cc.find("common", free_times).active = true;
            cc.find("common/allTimes", free_times).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
            cc.find("common/curTimes", free_times).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree() - cc.vv.gameData.GetFreeTime();

            // cc.find("spr_bg_free", this.node.parent).getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetSpriteFrameByName("theme130_bg_free3");
        } else {
            this._curFreeTimesPanel = cc.find("mult_" + mult, free_times);
            cc.find("mult_" + mult, free_times).active = true;
            cc.find("mult_" + mult + "/allTimes", free_times).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
            cc.find("mult_" + mult + "/curTimes", free_times).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree() - cc.vv.gameData.GetFreeTime();

            // let spriteFrameName = "theme130_bg_free1";
            // if (mult === 3) {
            //     spriteFrameName = "theme130_bg_free2";
            // } else if (mult === 5) {
            //     spriteFrameName = "theme130_bg_free4";
            // }
            // cc.find("spr_bg_free", this.node.parent).getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetSpriteFrameByName(spriteFrameName);
        }
    },

    popFreeDialog(isCommon, isExtra, mult) {
        return new Promise(async (success)=>{

            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let free_bg = cc.find("free_dialog_bg", free_dialog);
            free_bg.opacity = 0;
            free_bg.runAction(cc.fadeTo(0.2, 200));

            let dialog = null;
            if (isCommon) {
                dialog = cc.find("common_enter_node", free_dialog);
                cc.vv.AudioManager.playEff("games/TheMammoth/", "fg_start", true);
            } else if (isExtra) {
                dialog = cc.find("extra_node", free_dialog);
                cc.vv.AudioManager.playEff("games/TheMammoth/", "retrigger_board_land", true);
            } else {
                cc.vv.AudioManager.playEff("games/TheMammoth/", "fg_start", true);
                dialog = cc.find("mult_enter_node_" + mult, free_dialog);
            }

            dialog.active = true;
            dialog.scale = 0;

            cc.find("times", dialog).getComponent(cc.Label).string =
                isExtra ? this._gameInfo.freeResult.freeInfo.freeCnt : cc.vv.gameData.GetTotalFree();

            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .call(async ()=>{
                    if (cc.find("btn_start", dialog)) {
                        let func = async ()=>{
                            cc.find("btn_start", dialog).off("click");
                            cc.vv.AudioManager.playEff("games/TheMammoth/", "fg_select", true);
                            cc.tween(dialog)
                                .to(0.5, {scale: 0})
                                .start();

                            free_bg.runAction(cc.fadeOut(0.2));

                            await cc.vv.gameData.awaitTime(0.5);

                            success();
                            dialog.active = false;
                            free_dialog.active = false;
                        }
                        cc.vv.gameData.checkAutoPlay(cc.find("btn_start", dialog), func);
                        cc.find("btn_start", dialog).on("click", async ()=>{
                            cc.find("btn_start", dialog).stopAllActions();
                            await func();
                        });
                    } else {
                        await cc.vv.gameData.awaitTime(2);
                        cc.tween(dialog)
                            .to(0.5, {scale: 0})
                            .start();

                        free_bg.runAction(cc.fadeOut(0.2));

                        await cc.vv.gameData.awaitTime(0.5);

                        success();
                        dialog.active = false;
                        free_dialog.active = false;
                    }
                })
                .start();
        });
    },

    popFreeResultDialog() {
        return new Promise(async (success)=>{
            cc.vv.AudioManager.playEff("games/TheMammoth/", "fg_end", true);

            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let free_bg = cc.find("free_dialog_bg", free_dialog);
            free_bg.opacity = 0;
            free_bg.runAction(cc.fadeTo(0.2, 200));

            let dialog = cc.find("result_node", free_dialog);

            dialog.active = true;
            dialog.scale = 0;
            cc.find("coin", dialog).getComponent(cc.Label).string = "";

            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            Global.doRoallNumEff(cc.find("coin", dialog), 0, cc.vv.gameData.GetGameTotalFreeWin(), 3, null, null, 0, true);

            let func = async ()=>{
                cc.find("btn_collect", dialog).off("click");
                cc.vv.AudioManager.playEff("games/TheMammoth/", "board_collect", true);
                cc.tween(dialog)
                    .to(0.5, {scale: 0})
                    .start();

                free_bg.runAction(cc.fadeOut(0.2));

                await cc.vv.gameData.awaitTime(0.5);
                success();
                dialog.active = false;
                free_dialog.active = false;
            }
            cc.vv.gameData.checkAutoPlay(cc.find("btn_collect", dialog), func);
            cc.find("btn_collect", dialog).on("click", async ()=>{
                cc.find("btn_collect", dialog).stopAllActions();
                await func();
            });
        })
    },

    awaitTime(time) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, time);
        });
    },
});
